#!/bin/bash
# =====================================================================
#  debian13-base-install.sh
#  Run this ONCE on a fresh Debian 13 (trixie) MINIMAL install, in the terminal (TTY).
#  It installs only the basics needed for a working Hyprland desktop:
#  network, login screen, audio / bluetooth / wifi / graphics drivers,
#  Hyprland + Quickshell (Debian backports), kitty, Thunar, Mousepad,
#  fonts + icon font, Brave Origin (1st) and LibreWolf (2nd).
#  Nothing else. No design, no theme, no personal config.
#
#    bash debian13-base-install.sh              install everything
#    bash debian13-base-install.sh --dry-run    show what would happen, change nothing
#    bash debian13-base-install.sh --skip-nvidia      do not install the NVIDIA driver
#    bash debian13-base-install.sh --skip-browsers    do not add Brave / LibreWolf repositories
#    bash debian13-base-install.sh --keep-network     do not switch networking to NetworkManager
#
#  Needs: internet already working (the Debian installer usually leaves it working),
#         and root (run as root, or as a user that has sudo).
#  Safe to run again: it only adds what is missing.
#  Log file: /var/log/debian13-base-install.log
# =====================================================================
set -u
DRY=0; SKIP_NVIDIA=0; SKIP_BROWSERS=0; KEEP_NET=0
for a in "$@"; do case "$a" in
  --dry-run) DRY=1;; --skip-nvidia) SKIP_NVIDIA=1;; --skip-browsers) SKIP_BROWSERS=1;; --keep-network) KEEP_NET=1;;
  *) echo "unknown option: $a"; exit 2;; esac; done

# ---- must be root: re-run with sudo if needed
if [ "$(id -u)" != "0" ]; then
  if command -v sudo >/dev/null 2>&1; then exec sudo -E bash "$0" "$@"; fi
  echo "This script needs root. Become root with:   su -"
  echo "then run it again:   bash $(readlink -f "$0")"
  exit 1
fi

ROOT="${DEBINST_TEST_ROOT:-}"      # (only for testing in a fake folder)
LOG="$ROOT/var/log/debian13-base-install.log"
mkdir -p "$(dirname "$LOG")" 2>/dev/null
[ "$DRY" = 1 ] || exec > >(tee -a "$LOG") 2>&1

PROBLEMS=0; WARNS=0
ok(){ echo "  [OK]      $*"; }
info(){ echo "  [..]      $*"; }
warn(){ echo "  [WARN]    $*"; WARNS=$((WARNS+1)); }
prob(){ echo "  [PROBLEM] $*"; PROBLEMS=$((PROBLEMS+1)); }
run(){ if [ "$DRY" = 1 ]; then echo "  [dry-run] $*"; else "$@"; fi; }
export DEBIAN_FRONTEND=noninteractive

# ---------------------------------------------------------------- 0. checks
echo "== 0. Checking the system =="
CODENAME="$(. "$ROOT/etc/os-release" 2>/dev/null; echo "${VERSION_CODENAME:-unknown}")"
if [ "$CODENAME" != "trixie" ] && [ -z "${DEBINST_ALLOW_ANY:-}" ]; then
  echo "This script is for Debian 13 (trixie). This system says: $CODENAME. Stopping."; exit 1
fi
ok "Debian 13 (trixie)"
[ "$(dpkg --print-architecture)" = "amd64" ] && ok "architecture amd64" || warn "architecture is $(dpkg --print-architecture), not amd64: Brave / NVIDIA steps may not work"
if [ "$DRY" != 1 ]; then
  if ! (getent hosts deb.debian.org >/dev/null 2>&1 || ping -c1 -W3 deb.debian.org >/dev/null 2>&1); then
    echo "The internet is not working. Connect first (cable, or: the installer's Wi-Fi), then run this script again."; exit 1
  fi
fi
ok "internet works"
TARGET_USER="${SUDO_USER:-$(getent passwd 1000 | cut -d: -f1)}"
[ -n "$TARGET_USER" ] && ok "your normal user: $TARGET_USER" || warn "no normal user (uid 1000) found"
command -v mokutil >/dev/null 2>&1 && mokutil --sb-state 2>/dev/null | grep -qi enabled && \
  warn "Secure Boot is ON. The NVIDIA driver (dkms) needs a Secure Boot key (MOK) or Secure Boot off; Debian will ask for a password during the driver install."
GPU="other"
lspci 2>/dev/null | grep -Ei 'vga|3d|display' | grep -qi nvidia && GPU="nvidia"
lspci 2>/dev/null | grep -Ei 'vga|3d|display' | grep -qiE 'amd|ati|radeon' && GPU="${GPU/other/amd}"
lspci 2>/dev/null | grep -Ei 'vga|3d|display' | grep -qi intel && GPU="${GPU/other/intel}"
info "graphics card detected: $GPU"

# ---------------------------------------------------------------- 1. apt sources
echo; echo "== 1. APT sources (contrib, non-free, non-free-firmware, backports) =="
SRC_DIR="$ROOT/etc/apt/sources.list.d"; SRC_LIST="$ROOT/etc/apt/sources.list"
TS="$(date +%Y%m%d-%H%M%S)"
ensure_components_deb822(){ # $1 = file
  local f="$1" changed=0
  grep -q '^Components:' "$f" || return 0
  cp "$f" "$f.before-base-install-$TS"
  awk '
    /^Components:/ { n=split("main contrib non-free non-free-firmware", w, " ")
      line=$0; for (i=1;i<=n;i++) { if ((" " line " ") !~ (" " w[i] " ")) line=line " " w[i] } print line; next }
    { print }' "$f.before-base-install-$TS" > "$f.new" && mv "$f.new" "$f"
  cmp -s "$f" "$f.before-base-install-$TS" && { rm -f "$f.before-base-install-$TS"; return 0; }
  ok "added missing components in $f (backup: $f.before-base-install-$TS)"
}
ensure_components_oneline(){ # $1 = file
  local f="$1"
  grep -qE '^deb(-src)? +[^[]' "$f" || return 0
  cp "$f" "$f.before-base-install-$TS"
  awk '/^deb(-src)? +[^[]/ { n=split("main contrib non-free non-free-firmware", w, " ");
         for (i=1;i<=n;i++) { if ((" " $0 " ") !~ (" " w[i] " ")) $0=$0 " " w[i] } } { print }' "$f.before-base-install-$TS" > "$f.new" && mv "$f.new" "$f"
  cmp -s "$f" "$f.before-base-install-$TS" && { rm -f "$f.before-base-install-$TS"; return 0; }
  ok "added missing components in $f (backup: $f.before-base-install-$TS)"
}
if [ "$DRY" = 1 ]; then
  info "would add contrib / non-free / non-free-firmware to the Debian sources and enable trixie-backports"
else
  for f in "$SRC_DIR"/*.sources; do [ -f "$f" ] && grep -q 'deb.debian.org\|security.debian.org\|debian.org/debian' "$f" && ensure_components_deb822 "$f"; done
  [ -f "$SRC_LIST" ] && ensure_components_oneline "$SRC_LIST"
  if grep -rqs 'trixie-backports' "$SRC_DIR" "$SRC_LIST" 2>/dev/null; then ok "trixie-backports already enabled"
  else
    mkdir -p "$SRC_DIR"
    cat > "$SRC_DIR/debian-backports.sources" <<'EOF_BP'
Types: deb
URIs: http://deb.debian.org/debian
Suites: trixie-backports
Components: main contrib non-free non-free-firmware
Signed-By: /usr/share/keyrings/debian-archive-keyring.gpg
EOF_BP
    ok "enabled trixie-backports (Debian's official repository for newer software)"
  fi
fi
if [ "$DRY" != 1 ] && [ -z "$ROOT" ]; then
  apt-get update || { echo "apt-get update failed: check the internet and /etc/apt/sources.list.d, then run again."; exit 1; }
fi

# ---------------------------------------------------------------- helpers to install
FAILED=(); MISSING=()
avail(){ apt-cache policy "$1" 2>/dev/null | awk '/Candidate:/ {print $2}' | grep -qv '(none)' ; }
avail_bp(){ apt-cache madison "$1" 2>/dev/null | grep -q 'trixie-backports'; }
inst(){ # inst <label> <pkg...>   (normal archive)
  local label="$1"; shift; local ok_list=() p
  for p in "$@"; do if [ "$DRY" = 1 ] || avail "$p"; then ok_list+=("$p"); else MISSING+=("$p"); warn "package not found: $p"; fi; done
  [ "${#ok_list[@]}" -gt 0 ] || return 0
  info "$label: ${ok_list[*]}"
  if [ "$DRY" = 1 ]; then echo "  [dry-run] apt-get install -y ${ok_list[*]}"; return 0; fi
  if ! apt-get install -y "${ok_list[@]}"; then
    warn "group failed, trying one by one"
    for p in "${ok_list[@]}"; do apt-get install -y "$p" || { FAILED+=("$p"); prob "could not install $p"; }; done
  fi
}
inst_bp(){ # inst_bp <label> <pkg...>   (from trixie-backports, explicitly requested)
  local label="$1"; shift; local ok_list=() p
  for p in "$@"; do if [ "$DRY" = 1 ] || avail_bp "$p"; then ok_list+=("$p"); else MISSING+=("$p"); warn "not in trixie-backports: $p"; fi; done
  [ "${#ok_list[@]}" -gt 0 ] || return 0
  info "$label (backports): ${ok_list[*]}"
  if [ "$DRY" = 1 ]; then echo "  [dry-run] apt-get install -y --no-install-recommends -t trixie-backports ${ok_list[*]}"; return 0; fi
  apt-get install -y --no-install-recommends -t trixie-backports "${ok_list[@]}" || { FAILED+=("${ok_list[@]}"); prob "backports install failed: ${ok_list[*]} (see the message above)"; }
}

# ---------------------------------------------------------------- 2. basics
echo; echo "== 2. Basic tools =="
inst "basics" ca-certificates curl wget gnupg pciutils usbutils iw rfkill iproute2 iputils-ping xdg-utils xdg-user-dirs sudo \
     fontconfig dbus-user-session polkitd pkexec

# ---------------------------------------------------------------- 3. firmware + microcode + wifi
echo; echo "== 3. Firmware, Wi-Fi, CPU microcode =="
inst "firmware (wifi, bluetooth, graphics, audio)" firmware-linux firmware-sof-signed wireless-regdb
if grep -q GenuineIntel "$ROOT/proc/cpuinfo" 2>/dev/null || [ "$DRY" = 1 ]; then inst "intel microcode" intel-microcode; fi
if grep -q AuthenticAMD "$ROOT/proc/cpuinfo" 2>/dev/null; then inst "amd microcode" amd64-microcode; fi

# ---------------------------------------------------------------- 4. network
echo; echo "== 4. Network (NetworkManager) =="
inst "network" network-manager wpasupplicant
if [ "$DRY" = 1 ]; then info "would enable NetworkManager"; elif systemctl enable NetworkManager >/dev/null 2>&1; then ok "NetworkManager enabled"; else prob "could not enable NetworkManager"; fi

# ---------------------------------------------------------------- 5. graphics
echo; echo "== 5. Graphics drivers =="
inst "mesa (open drivers for AMD / Intel, also needed by Wayland)" libgl1-mesa-dri mesa-vulkan-drivers libegl1 libgbm1 libglx-mesa0
if [ "$SKIP_NVIDIA" = 1 ]; then info "NVIDIA driver skipped (--skip-nvidia)"
elif [ "$GPU" = "nvidia" ] || [ "$DRY" = 1 ]; then
  inst "NVIDIA kernel headers + driver" dkms linux-headers-amd64 nvidia-driver nvidia-kernel-dkms firmware-misc-nonfree
  if [ "$DRY" != 1 ]; then
    printf 'options nvidia_drm modeset=1 fbdev=1\noptions nvidia NVreg_PreserveVideoMemoryAllocations=1\n' > "$ROOT/etc/modprobe.d/nvidia-wayland.conf"
    ok "wrote /etc/modprobe.d/nvidia-wayland.conf (modeset for Wayland, keep video memory over sleep)"
    for u in nvidia-suspend nvidia-resume nvidia-hibernate; do
      systemctl cat "$u.service" >/dev/null 2>&1 && systemctl enable "$u.service" >/dev/null 2>&1 && info "enabled $u.service"
    done
    update-initramfs -u >/dev/null 2>&1 && ok "initramfs updated" || warn "update-initramfs failed"
  fi
else info "no NVIDIA card: nothing to install"; fi

# ---------------------------------------------------------------- 6. audio + bluetooth
echo; echo "== 6. Audio and Bluetooth =="
inst "audio" pipewire-audio alsa-utils pulseaudio-utils
inst "bluetooth" bluez bluetooth
if [ "$DRY" = 1 ]; then info "would enable bluetooth"; elif systemctl enable bluetooth >/dev/null 2>&1; then ok "bluetooth service enabled"; else warn "could not enable the bluetooth service"; fi

# ---------------------------------------------------------------- 7. desktop (hyprland + quickshell)
echo; echo "== 7. Hyprland + Quickshell (from trixie-backports) =="
inst "wayland basics" xwayland qt6-wayland xdg-desktop-portal-gtk
inst_bp "hyprland, quickshell, portals" libxkbcommon0 hyprland hyprland-guiutils quickshell xdg-desktop-portal-hyprland hyprpolkitagent
if [ "$DRY" != 1 ] && ! ls "$ROOT"/usr/share/wayland-sessions/hyprland*.desktop >/dev/null 2>&1; then
  prob "Hyprland session file not found in /usr/share/wayland-sessions: the login screen would not offer Hyprland"
fi

# ---------------------------------------------------------------- 8. login screen
echo; echo "== 8. Login screen (SDDM) =="
inst "display manager" sddm
if [ "$DRY" != 1 ]; then
  if command -v sddm >/dev/null 2>&1; then
    command -v sddm > "$ROOT/etc/X11/default-display-manager" 2>/dev/null
    systemctl enable sddm >/dev/null 2>&1 && ok "SDDM is the login screen (starts at the next boot)" || prob "could not enable sddm"
  fi
fi

# ---------------------------------------------------------------- 9. apps
echo; echo "== 9. Apps: terminal, file manager, editor =="
inst "apps" kitty thunar thunar-volman gvfs udisks2 tumbler mousepad adwaita-icon-theme

# ---------------------------------------------------------------- 10. fonts
echo; echo "== 10. Fonts and icon font =="
inst "fonts" fonts-inter fonts-jetbrains-mono fonts-montserrat fonts-noto-core fonts-noto-color-emoji
if [ "$DRY" = 1 ]; then info "would install the icon font Material Symbols Rounded to /usr/local/share/fonts"
else
  FD="$ROOT/usr/local/share/fonts/material-symbols"; mkdir -p "$FD"
  tmp="$(mktemp)"
  base64 -d <<'FONT_B64_EOF' | gzip -dc > "$tmp"
