FONT_B64_EOF
  if [ "$(sha256sum "$tmp" | cut -d' ' -f1)" = "210aa29b8b614a88f9195626a42952298f83b1db7ccf291be95eb42c58f4da78" ]; then
    install -m 644 "$tmp" "$FD/MaterialSymbolsRounded.ttf"
    echo "Material Symbols Rounded - Copyright Google LLC - Apache License 2.0 - https://github.com/google/material-design-icons" > "$FD/NOTICE.txt"
    ok "icon font installed (Material Symbols Rounded, system-wide)"
  else prob "embedded icon font is damaged (checksum differs). Download this script again."; fi
  rm -f "$tmp"
  command -v fc-cache >/dev/null 2>&1 && fc-cache -f >/dev/null 2>&1
fi

# ---------------------------------------------------------------- 11. browsers
echo; echo "== 11. Browsers: Brave Origin (1st), LibreWolf (2nd) =="
if [ "$SKIP_BROWSERS" = 1 ]; then info "browsers skipped (--skip-browsers)"
else
  # Brave Origin: Brave's own official apt repository (package: brave-origin)
  if [ "$DRY" = 1 ]; then
    info "would add Brave's apt repository and install brave-origin"
  else
    if curl -fsSLo /usr/share/keyrings/brave-browser-archive-keyring.gpg https://brave-browser-apt-release.s3.brave.com/brave-browser-archive-keyring.gpg \
       && curl -fsSLo /etc/apt/sources.list.d/brave-browser-release.sources https://brave-browser-apt-release.s3.brave.com/brave-browser.sources \
       && apt-get update >/dev/null 2>&1; then
      apt-get install -y brave-origin && ok "Brave Origin installed" || prob "Brave Origin install failed (later: sudo apt install brave-origin)"
    else prob "could not add the Brave repository (internet?). Later: see https://brave.com/origin/linux/"; fi
  fi
  # LibreWolf: through extrepo (Debian's own tool for trusted external repositories)
  inst "extrepo" extrepo
  if [ "$DRY" = 1 ]; then info "would run: extrepo enable librewolf, then install librewolf"
  elif command -v extrepo >/dev/null 2>&1; then
    if extrepo enable librewolf && extrepo update librewolf && apt-get update >/dev/null 2>&1 && apt-get install -y librewolf; then ok "LibreWolf installed"
    else prob "LibreWolf install failed (later: https://librewolf.net/installation/debian/)"; fi
  else prob "extrepo is not installed, LibreWolf skipped"; fi
  # default browser: Brave Origin if present, otherwise LibreWolf
  if [ "$DRY" != 1 ] && [ -n "$TARGET_USER" ]; then
    for d in brave-origin.desktop librewolf.desktop; do
      if [ -f "/usr/share/applications/$d" ]; then runuser -u "$TARGET_USER" -- xdg-settings set default-web-browser "$d" >/dev/null 2>&1 && info "default browser: $d"; break; fi
    done
  fi
fi

# ---------------------------------------------------------------- 12. network takeover (last on purpose)
echo; echo "== 12. Switch networking to NetworkManager =="
IF="$ROOT/etc/network/interfaces"
if [ "$KEEP_NET" = 1 ]; then info "kept the old network setup (--keep-network)"
elif [ "$DRY" = 1 ]; then info "would comment out the non-loopback entries in /etc/network/interfaces so NetworkManager manages the network"
elif [ -f "$IF" ] && command -v nmcli >/dev/null 2>&1; then
  if awk '/^(auto|allow-hotplug|iface)[ \t]+/ && $2!="lo" {f=1} END{exit !f}' "$IF"; then
    cp "$IF" "$IF.before-base-install-$TS"
    awk '
      /^[ \t]*(auto|allow-hotplug|iface|mapping)[ \t]+/ { name=$2; skip=(name!="lo") }
      /^[ \t]*(source|source-directory)[ \t]+/ { skip=0 }
      /^[ \t]*$/ { skip=0 }
      { if (skip && $0 !~ /^[ \t]*#/) print "#" $0; else print }' "$IF.before-base-install-$TS" > "$IF"
    ok "old network entries commented out (backup: $IF.before-base-install-$TS)"
    info "NetworkManager takes over at the next boot. Wi-Fi / cable: use  nmtui  in the terminal."
    info "If the network does not come up after reboot:  sudo cp $IF.before-base-install-$TS /etc/network/interfaces ; sudo systemctl disable NetworkManager ; sudo reboot"
  else ok "no old network entries found, nothing to change"; fi
else info "nothing to change"; fi

# ---------------------------------------------------------------- 13. verify
echo; echo "== 13. Checking the result =="
if [ "$DRY" = 1 ]; then info "dry run: nothing was installed"
else
  chk(){ dpkg -s "$1" >/dev/null 2>&1 && ok "$1" || prob "$1 is NOT installed"; }
  for p in network-manager firmware-linux pipewire-audio bluez sddm kitty thunar mousepad fonts-inter hyprland quickshell; do chk "$p"; done
  [ "$GPU" = "nvidia" ] && [ "$SKIP_NVIDIA" = 0 ] && chk nvidia-driver
  fc-list 2>/dev/null | grep -qi "Material Symbols Rounded" && ok "icon font visible" || prob "icon font not visible"
  systemctl is-enabled sddm >/dev/null 2>&1 && ok "sddm enabled" || prob "sddm not enabled"
  systemctl is-enabled NetworkManager >/dev/null 2>&1 && ok "NetworkManager enabled" || prob "NetworkManager not enabled"
  dpkg -s brave-origin >/dev/null 2>&1 && ok "brave-origin" || warn "brave-origin not installed"
  dpkg -s librewolf >/dev/null 2>&1 && ok "librewolf" || warn "librewolf not installed"
fi

echo
if [ "$PROBLEMS" -eq 0 ]; then echo "DONE, no problems.  ($WARNS warning(s))"; else echo "FINISHED WITH $PROBLEMS PROBLEM(S) - see [PROBLEM] lines above."; fi
cat <<'MSG'

Next:  sudo reboot
At the login screen choose the session "Hyprland" (bottom corner), type your password.
First start has Hyprland's own default settings (no design yet). A terminal usually opens with Super+Q (kitty is installed); if not, press Ctrl+Alt+F3 for a text console.
Wi-Fi in the terminal:   nmtui
Full log: /var/log/debian13-base-install.log
MSG
[ "$PROBLEMS" -eq 0 ]
